import{bV as r,aL as t,u as e,G as o}from"./chunks/framework.BfzMay2U.js";const c=JSON.parse('{"title":"制造业 PHP 面试题：MES、E-DHR 与 OA（76—100）","description":"","frontmatter":{"title":"制造业 PHP 面试题：MES、E-DHR 与 OA（76—100）","date":"2026-11-15T10:30:00.000Z","categories":["面试","PHP"],"tags":["MES","E-DHR","OA","医疗器械","审计追踪","电子记录"],"sidebarSort":4},"headers":[],"relativePath":"php/jd/mes-edhr-oa-interview.md","filePath":"php/jd/mes-edhr-oa-interview.md"}'),n={name:"php/jd/mes-edhr-oa-interview.md"};function s(h,a,i,l,p,d){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="制造业-php-面试题-mes、e-dhr-与-oa-76—100" tabindex="-1">制造业 PHP 面试题：MES、E-DHR 与 OA（76—100） <a class="header-anchor" href="#制造业-php-面试题-mes、e-dhr-与-oa-76—100" aria-label="Permalink to &quot;制造业 PHP 面试题：MES、E-DHR 与 OA（76—100）&quot;">​</a></h1><p>本篇重点是将业务规则转成字段、状态、权限、校验与证据。E-DHR 指 Electronic Device History Record，可理解为电子器械历史记录；企业中也常围绕生产批次组织相关记录，其具体范围应由实际产品与质量流程定义。</p><div class="warning custom-block"><p class="custom-block-title">回答边界</p><p>这些是软件设计与面试准备建议。法规适用范围、记录保存期限、签名方式和验证要求，应由企业质量及法规人员结合产品、市场和预期用途确认，不能用“做了日志”直接推出系统合规。</p></div><h2 id="一、生产与质量链路" tabindex="-1">一、生产与质量链路 <a class="header-anchor" href="#一、生产与质量链路" aria-label="Permalink to &quot;一、生产与质量链路&quot;">​</a></h2><h3 id="_76-如何讲清从工单到入库的一条完整生产链路" tabindex="-1">76. 如何讲清从工单到入库的一条完整生产链路？ <a class="header-anchor" href="#_76-如何讲清从工单到入库的一条完整生产链路" aria-label="Permalink to &quot;76. 如何讲清从工单到入库的一条完整生产链路？&quot;">​</a></h3><p><strong>参考回答：</strong> 从工单及版本释放开始，关联工艺路线、物料批次和设备，执行各工序并报工，记录物料消耗和生产参数，完成检验、偏差处理与审核放行，再形成入库及 ERP 同步。每个节点明确触发条件、责任角色、业务编号和异常出口。</p><p><strong>追问要点：</strong> 不是所有企业都按固定顺序运行，部分检验可穿插在工序中；应以实际工艺和质量规则确定哪些条件必须阻断后续动作。</p><h3 id="_77-工单和工序状态机应该怎样设计" tabindex="-1">77. 工单和工序状态机应该怎样设计？ <a class="header-anchor" href="#_77-工单和工序状态机应该怎样设计" aria-label="Permalink to &quot;77. 工单和工序状态机应该怎样设计？&quot;">​</a></h3><p><strong>参考回答：</strong> 将状态和允许动作列成转换表，注明角色、前置条件和副作用。例如工单从草稿到已释放、执行中、暂停、完成、关闭；工序有独立进度，不能用一个工单状态代替所有工序事实。每次转换做并发校验并留审计。</p><p><strong>追问要点：</strong> 取消执行中的工单通常涉及已消耗物料、在制品和 ERP 状态，不能直接把状态改回草稿，必须定义退料、结算或冲销规则。</p><h3 id="_78-工艺路线、bom-和检验标准变更后-历史记录怎么办" tabindex="-1">78. 工艺路线、BOM 和检验标准变更后，历史记录怎么办？ <a class="header-anchor" href="#_78-工艺路线、bom-和检验标准变更后-历史记录怎么办" aria-label="Permalink to &quot;78. 工艺路线、BOM 和检验标准变更后，历史记录怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 使用受控版本，工单释放时绑定适用版本或快照，历史记录继续引用当时生效的规则。新版本的审批、生效时间和适用范围明确记录；在制品是否切换由业务和质量评估后通过受控变更执行。</p><p><strong>追问要点：</strong> 不应直接更新主数据后让历史报工展示新标准，否则无法重建“当时为什么判定合格”。</p><h3 id="_79-报工接口应该校验哪些业务条件" tabindex="-1">79. 报工接口应该校验哪些业务条件？ <a class="header-anchor" href="#_79-报工接口应该校验哪些业务条件" aria-label="Permalink to &quot;79. 报工接口应该校验哪些业务条件？&quot;">​</a></h3><p><strong>参考回答：</strong> 校验操作者及工厂权限、工单和工序状态、设备或工位绑定、前序条件、批次有效性、数量精度、良品与报废关系、物料与质量约束，并防止重复。动态条件在事务内核对，超量或补录按明确权限和审批规则处理。</p><p><strong>追问要点：</strong> 必须确认报工数量是本次增量还是累计值，两种语义混用会重复累计；返工数量也不能直接加到首次产出中。</p><h3 id="_80-批次拆分与合并如何实现追溯" tabindex="-1">80. 批次拆分与合并如何实现追溯？ <a class="header-anchor" href="#_80-批次拆分与合并如何实现追溯" aria-label="Permalink to &quot;80. 批次拆分与合并如何实现追溯？&quot;">​</a></h3><p><strong>参考回答：</strong> 建立输入批次到输出批次的关系记录，保留操作、数量、单位、损耗和原因。拆分形成一个父批次到多个子批次，合并可能多个输入到一个输出，不能仅用一个 <code>parent_id</code> 覆盖全部关系。</p><p><strong>追问要点：</strong> 防止关系循环，验证数量平衡和允许混批条件；合并后仍要能反查每个供应商批次及受影响成品。</p><h3 id="_81-领料、耗料、退料、补料有什么区别" tabindex="-1">81. 领料、耗料、退料、补料有什么区别？ <a class="header-anchor" href="#_81-领料、耗料、退料、补料有什么区别" aria-label="Permalink to &quot;81. 领料、耗料、退料、补料有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 领料描述物料转移或发放，耗料描述实际生产消耗，退料描述未消耗物料退回，补料是追加投入；它们的库存地点、可用量和成本含义可能不同。应采用带来源单据的业务流水，而不是只改库存最终值。</p><p><strong>追问要点：</strong> BOM 理论消耗和实际消耗可能不同，自动倒扣的触发时点、损耗率、替代料和差异审批要由业务明确。</p><h3 id="_82-返工、返修和报废为什么不能直接修改原报工数量" tabindex="-1">82. 返工、返修和报废为什么不能直接修改原报工数量？ <a class="header-anchor" href="#_82-返工、返修和报废为什么不能直接修改原报工数量" aria-label="Permalink to &quot;82. 返工、返修和报废为什么不能直接修改原报工数量？&quot;">​</a></h3><p><strong>参考回答：</strong> 原报工是已经发生的生产事实，直接覆盖会破坏历史与对账。返工或返修应关联原批次和原因，定义新工序、检验及产出规则；报废形成受控记录和对应库存动作。合法更正也应保留原值、原因、操作人和版本。</p><p><strong>追问要点：</strong> 返工后合格不代表首次合格，应区分最终合格率和一次通过率，避免指标失真。</p><h3 id="_83-质量检验模块最重要的建模点是什么" tabindex="-1">83. 质量检验模块最重要的建模点是什么？ <a class="header-anchor" href="#_83-质量检验模块最重要的建模点是什么" aria-label="Permalink to &quot;83. 质量检验模块最重要的建模点是什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 区分检验任务、样本、检验项目、原始结果、规则版本和最终判定，保存单位、精度、上下限、设备及操作者。判定规则考虑边界值、缺失值、无效测量和复测，不以一个“合格”布尔字段代替所有依据。</p><p><strong>追问要点：</strong> 抽样方法和接受准则应引用已批准的质量规则，开发不自行创造；复测不能静默覆盖首次失败结果。</p><h3 id="_84-有一项检验不合格-系统应该如何阻断" tabindex="-1">84. 有一项检验不合格，系统应该如何阻断？ <a class="header-anchor" href="#_84-有一项检验不合格-系统应该如何阻断" aria-label="Permalink to &quot;84. 有一项检验不合格，系统应该如何阻断？&quot;">​</a></h3><p><strong>参考回答：</strong> 根据规则冻结相关批次、工序或后续放行，产生不合格或偏差处理记录，由有权限人员评审处置。重检、返工、报废或特定批准要有明确路径，并与入库和对外同步保持一致。</p><p><strong>追问要点：</strong> 不能仅在页面按钮上限制，API、批量导入、后台任务都必须执行相同规则；管理员身份不应默认跳过质量门禁。</p><h3 id="_85-入库和质量放行是否是同一个动作" tabindex="-1">85. 入库和质量放行是否是同一个动作？ <a class="header-anchor" href="#_85-入库和质量放行是否是同一个动作" aria-label="Permalink to &quot;85. 入库和质量放行是否是同一个动作？&quot;">​</a></h3><p><strong>参考回答：</strong> 不一定。实物可进入待检或隔离库位，但未必允许成为可领用、可销售库存；质量放行、实物入库和财务过账通常是不同维度。应明确可用库存的条件和每一步的系统责任。</p><p><strong>追问要点：</strong> 若 ERP 入库成功而 MES 状态更新失败，应按来源单据查询并修复一致性，避免重新创建第二张入库单。</p><h3 id="_86-召回追溯功能怎样验证有效" tabindex="-1">86. 召回追溯功能怎样验证有效？ <a class="header-anchor" href="#_86-召回追溯功能怎样验证有效" aria-label="Permalink to &quot;86. 召回追溯功能怎样验证有效？&quot;">​</a></h3><p><strong>参考回答：</strong> 从一个原材料批次正向找到消耗、在制品、成品批次及发运，从成品反向找到来源物料、工序、设备、人员、参数和质量记录。覆盖拆分、合并、替代、返工和历史归档，验证完整性和查询耗时。</p><p><strong>追问要点：</strong> 结果应展示来源、数量及关系依据，并验证跨工厂权限；不能用当前 BOM 推算历史真实投料关系。</p><h2 id="二、电子记录、权限与审计" tabindex="-1">二、电子记录、权限与审计 <a class="header-anchor" href="#二、电子记录、权限与审计" aria-label="Permalink to &quot;二、电子记录、权限与审计&quot;">​</a></h2><h3 id="_87-一份-e-dhr-应怎样组织-才能支持复核" tabindex="-1">87. 一份 E-DHR 应怎样组织，才能支持复核？ <a class="header-anchor" href="#_87-一份-e-dhr-应怎样组织-才能支持复核" aria-label="Permalink to &quot;87. 一份 E-DHR 应怎样组织，才能支持复核？&quot;">​</a></h3><p><strong>参考回答：</strong> 以器械或生产批次为入口，聚合适用版本、生产与物料记录、检验结果、偏差处置、签名与放行，并能定位每项记录的原始依据。采用清单明确必需内容及缺失项，复核看到的是受控版本和关联事实。</p><p><strong>追问要点：</strong> 仅导出一份 PDF 不等于完成电子记录管理，还要维护可检索、可归属、修订追踪和保留能力。</p><h3 id="_88-alcoa-如何落成开发要求" tabindex="-1">88. ALCOA+ 如何落成开发要求？ <a class="header-anchor" href="#_88-alcoa-如何落成开发要求" aria-label="Permalink to &quot;88. ALCOA+ 如何落成开发要求？&quot;">​</a></h3><p><strong>参考回答：</strong> 记录要能归属个人或设备、可读、及时、保留原始依据并准确；同时完整、一致、持久和可用。开发上体现为独立账号、原始数据保存、时间与版本字段、输入与换算校验、审计、备份和授权检索。</p><p><strong>追问要点：</strong> ALCOA+ 可作为数据完整性检查框架，但不是一个加字段就能自动获得的认证；人员流程和系统运行控制同样重要。</p><h3 id="_89-审计追踪与普通应用日志有什么区别" tabindex="-1">89. 审计追踪与普通应用日志有什么区别？ <a class="header-anchor" href="#_89-审计追踪与普通应用日志有什么区别" aria-label="Permalink to &quot;89. 审计追踪与普通应用日志有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 应用日志主要服务排障，审计追踪服务重建关键记录的创建、修改、审核或作废过程。审计需包含对象与版本、操作者、动作、时间、原因及必要前后值，访问和保留也应受控。</p><p><strong>追问要点：</strong> 请求日志不一定包含业务最终结果；异步写审计可能丢失关键证据。必须一起成立的业务变更与关键审计应同事务保存。</p><h3 id="_90-使用-eloquent-observer-就能完整记录所有审计吗" tabindex="-1">90. 使用 Eloquent Observer 就能完整记录所有审计吗？ <a class="header-anchor" href="#_90-使用-eloquent-observer-就能完整记录所有审计吗" aria-label="Permalink to &quot;90. 使用 Eloquent Observer 就能完整记录所有审计吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能。批量更新、原生 SQL、其他程序写库等路径可能不触发模型事件，而且事件未必知道业务原因、签名和状态语义。应让关键业务动作走明确的受控服务入口，在事务中写审计，并识别其他合法写入路径。</p><p><strong>追问要点：</strong> 数据库触发器也缺少完整业务身份上下文，不能简单替代应用审计；需要按实际架构组合控制并验证覆盖。</p><h3 id="_91-如何降低管理员篡改审计记录的风险" tabindex="-1">91. 如何降低管理员篡改审计记录的风险？ <a class="header-anchor" href="#_91-如何降低管理员篡改审计记录的风险" aria-label="Permalink to &quot;91. 如何降低管理员篡改审计记录的风险？&quot;">​</a></h3><p><strong>参考回答：</strong> 普通业务身份不允许更新或删除审计，应用、运维与数据库管理权限分离，关键记录可异地归集并按要求使用不可变存储、备份和访问告警。定期复核特权操作，并验证恢复和完整性检查流程。</p><p><strong>关键边界：</strong> 数据库超级用户通常仍具有很强能力，不能承诺单张表绝对不可篡改。哈希链能帮助发现改变，但若全部材料由同一人控制，也不能独立证明未被重建。</p><h3 id="_92-电子签名与点击-审核通过-有什么区别" tabindex="-1">92. 电子签名与点击“审核通过”有什么区别？ <a class="header-anchor" href="#_92-电子签名与点击-审核通过-有什么区别" aria-label="Permalink to &quot;92. 电子签名与点击“审核通过”有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 电子签名需要可信确认签署身份、签署意图，并与具体记录及其版本绑定，显示签署人、时间和含义，防止被复制到其他记录。具体认证和签名措施按适用要求确定，不能只在审核表填当前用户名。</p><p><strong>追问要点：</strong> 敏感认证凭证不写日志；签名失败不改变业务状态。技术上的数字签名可以是实现手段，但不能直接等同于完整的电子签名管理要求。</p><h3 id="_93-已经审核签名的批记录发现填错了-应该怎样修改" tabindex="-1">93. 已经审核签名的批记录发现填错了，应该怎样修改？ <a class="header-anchor" href="#_93-已经审核签名的批记录发现填错了-应该怎样修改" aria-label="Permalink to &quot;93. 已经审核签名的批记录发现填错了，应该怎样修改？&quot;">​</a></h3><p><strong>参考回答：</strong> 通过受控更正、补充记录或新版本表达变更，保留原记录、错误原因、申请人和复核。评估原签名、放行及外部系统是否受到影响，新的审核绑定更正后的版本，而不是静默继承原签名。</p><p><strong>追问要点：</strong> 不使用直接改库绕过流程；紧急处理也要有授权、证据、影响评估和后续复核。</p><h3 id="_94-权限模型如何支持工厂、车间和双人复核" tabindex="-1">94. 权限模型如何支持工厂、车间和双人复核？ <a class="header-anchor" href="#_94-权限模型如何支持工厂、车间和双人复核" aria-label="Permalink to &quot;94. 权限模型如何支持工厂、车间和双人复核？&quot;">​</a></h3><p><strong>参考回答：</strong> 功能权限表达能做什么，数据范围表达能操作哪里，字段权限控制可见与可改项；关键动作再按当前对象状态和人员资格授权。双人复核需要检查创建人与复核人是否不同，不能只看两个按钮是否被点击。</p><p><strong>追问要点：</strong> 共享账号无法可靠归属个人；临时授权需有期限、理由和审批，人员离职或岗位变化后要回收权限并处理待办。</p><h3 id="_95-记录时间、导出和长期保留应如何设计" tabindex="-1">95. 记录时间、导出和长期保留应如何设计？ <a class="header-anchor" href="#_95-记录时间、导出和长期保留应如何设计" aria-label="Permalink to &quot;95. 记录时间、导出和长期保留应如何设计？&quot;">​</a></h3><p><strong>参考回答：</strong> 使用明确时区策略，区分事件发生、接收、操作和签署时间，保留原始来源时间与偏差信息。导出包含标识、版本、单位、时间含义和必要审计关联；按批准期限保留数据及读取能力，并验证备份恢复与检索。</p><p><strong>追问要点：</strong> 不能任意补写为当前时间掩盖迟录，也不能把通用天数当作所有医疗器械记录的法定保留期限。</p><h2 id="三、oa-与可配置业务流程" tabindex="-1">三、OA 与可配置业务流程 <a class="header-anchor" href="#三、oa-与可配置业务流程" aria-label="Permalink to &quot;三、OA 与可配置业务流程&quot;">​</a></h2><h3 id="_96-一个基本-oa-审批流程需要哪些对象" tabindex="-1">96. 一个基本 OA 审批流程需要哪些对象？ <a class="header-anchor" href="#_96-一个基本-oa-审批流程需要哪些对象" aria-label="Permalink to &quot;96. 一个基本 OA 审批流程需要哪些对象？&quot;">​</a></h3><p><strong>参考回答：</strong> 流程定义及版本描述规则，流程实例描述一次申请，节点任务描述当前处理工作，动作记录描述同意、拒绝、转交等事实。申请表单与业务单据保持关联，不能只在业务表塞一个 <code>approver_id</code>。</p><p><strong>追问要点：</strong> 简单固定流程可按现有模式直接实现，只有明确需要频繁配置时才引入流程引擎；流程定义更改不应自动覆盖已运行实例。</p><h3 id="_97-串行审批、会签和或签怎样实现" tabindex="-1">97. 串行审批、会签和或签怎样实现？ <a class="header-anchor" href="#_97-串行审批、会签和或签怎样实现" aria-label="Permalink to &quot;97. 串行审批、会签和或签怎样实现？&quot;">​</a></h3><p><strong>参考回答：</strong> 串行按节点顺序推进；会签按规则要求全部或一定比例通过；或签允许符合条件的任意一人完成。需要在并发事务中判断节点是否已结束，避免两人同时通过时重复生成下游任务。</p><p><strong>追问要点：</strong> 明确拒绝优先级、弃权、超时和剩余待办处理，节点完结后旧任务操作应返回状态冲突并保留尝试信息。</p><h3 id="_98-撤回、驳回、转交、加签和代理应怎样处理" tabindex="-1">98. 撤回、驳回、转交、加签和代理应怎样处理？ <a class="header-anchor" href="#_98-撤回、驳回、转交、加签和代理应怎样处理" aria-label="Permalink to &quot;98. 撤回、驳回、转交、加签和代理应怎样处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 每个动作有独立前置条件和权限，明确是否撤销后续任务、回到哪个节点、是否重审以及谁承担责任。代理需有授权范围和期限，记录实际操作人及被代理人；不能简单把当前审批人字段改成另一个人。</p><p><strong>追问要点：</strong> 已触发 ERP 过账或质量放行的流程，撤回可能需要业务冲销，不能仅撤回 OA 记录。</p><h3 id="_99-可配置字段和插件定制怎样避免越做越复杂" tabindex="-1">99. 可配置字段和插件定制怎样避免越做越复杂？ <a class="header-anchor" href="#_99-可配置字段和插件定制怎样避免越做越复杂" aria-label="Permalink to &quot;99. 可配置字段和插件定制怎样避免越做越复杂？&quot;">​</a></h3><p><strong>参考回答：</strong> 先明确现有字段、规则和扩展点，只开放有业务价值的配置，例如字段类型、必填、可见范围与批准的计算规则。配置要版本化、校验、测试和受控发布，插件复用统一的权限、事务和审计入口。</p><p><strong>追问要点：</strong> 不允许配置直接执行任意 PHP、SQL 或不受控表达式。插件失败应明确回滚或降级策略，不能绕过关键质量校验。</p><h3 id="_100-面试官让你现场设计一个-批次放行-功能-如何回答" tabindex="-1">100. 面试官让你现场设计一个“批次放行”功能，如何回答？ <a class="header-anchor" href="#_100-面试官让你现场设计一个-批次放行-功能-如何回答" aria-label="Permalink to &quot;100. 面试官让你现场设计一个“批次放行”功能，如何回答？&quot;">​</a></h3><p><strong>参考回答：</strong> 先列放行条件：生产记录完整、检验合格、偏差关闭、签署人员有资格且版本一致；再设计状态与权限、记录和审计、并发控制以及对 ERP 的可靠通知。实施上在事务内锁定批次并核对相关受控状态，写放行事实、签名关联和 outbox。</p><p><strong>追问要点：</strong> 其他修改路径也必须遵守同一锁定或版本协议，单独锁住批次不必然阻止检验子记录被并发修改。测试需覆盖签名失败、并发放行、重复请求及同步超时。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./integration-device-interview.html">上一篇：系统集成与设备联网（51—75）</a></li><li><a href="./uniapp-mobile-interview.html">下一篇：UniApp、小程序与 APP（101—125）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="./../projects/medical-compliance-system.html">既有专题：E-DHR 系统与验证准备</a></li><li><a href="https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-11" target="_blank" rel="noreferrer">21 CFR Part 11 原文</a></li></ul>',83)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
